// Read-only field-write inventory; output remains in the private audit area.
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import java.io.*;
public class FindHardwareContactFields extends GhidraScript{public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){InstructionIterator it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){Instruction i=it.next();String s=i.toString();if((s.contains("+ 0xa2]")||s.contains("+ 0x7b]"))&&(i.getMnemonicString().equals("MOV")||i.getMnemonicString().equals("DEC")||i.getMnemonicString().equals("AND")||i.getMnemonicString().equals("OR"))){Function f=currentProgram.getFunctionManager().getFunctionContaining(i.getAddress());out.println((f==null?"null":f.getEntryPoint())+" "+i.getAddress()+" "+s);}}}}}
